(()=>{
const H=window.HBSTV,db=H.db,esc=escapeHtml;
const screen=document.createElement('section');screen.id='hub-screen';screen.hidden=true;document.querySelector('.content').append(screen);
document.querySelectorAll('.side-nav a').forEach(a=>{const href=a.getAttribute('href');if(href==='#arquivo')a.href='#campeonatos';if(href==='#acervo/news-competitive')a.href='#novidades';if(href==='#acervo'){const label=a.querySelector('span');if(label)label.textContent='Coleções';}});
document.querySelector('.side-nav').insertAdjacentHTML('afterbegin','<a href="#jogadores-todos">◈ <span>Jogadores</span><b>00</b></a>');
document.querySelector('footer').insertAdjacentHTML('beforeend','<a href="#manutencao">Manutenção dos registros ↗</a>');
const linkPlayer=id=>`<a class="hub-person" href="${H.playerHref(id)}"><span class="hub-silhouette" aria-hidden="true"></span><strong>${esc(H.name(id))}</strong><span>↗</span></a>`;
const header=(eyebrow,title,description)=>`<header class="hub-header"><span class="eyebrow">${esc(eyebrow)}</span><h2>${esc(title)}</h2><p>${esc(description)}</p></header>`;
const share=`<button class="hub-button" data-copy-link>Copiar link</button><span class="hub-feedback" role="status"></span>`;
let query='',year='',organizer='',majorOnly=false,playerQuery='';
const yearOptions=()=>[...new Set(db.events.map(e=>e.year))].sort((a,b)=>b-a).map(y=>`<option value="${y}" ${year===String(y)?'selected':''}>${y}</option>`).join('');
const orgOptions=()=>[...new Set(db.events.map(e=>e.organizer))].sort().map(o=>`<option ${organizer===o?'selected':''}>${esc(o)}</option>`).join('');
const matches=e=>(!year||e.year===+year)&&(!organizer||e.organizer===organizer)&&(!majorOnly||e.major)&&normalizeText(e.title+' '+e.winners.map(id=>db.teams.find(t=>t.id===id)?.name).join(' ')).includes(normalizeText(query));
function eventList(){const list=db.events.filter(matches);document.querySelector('#hub-event-count').textContent=list.length+' campeonatos';document.querySelector('#hub-event-list').innerHTML=list.length?list.map(e=>`<a class="hub-event-card ${e.major?'hub-major':''}" href="${H.eventHref(e.id)}">${window.renderOrganizationEmblem(e.title)}<span><small>${e.year} · ${esc(e.organizer)}</small><strong>${esc(e.title)}</strong><small>${e.winners.length?'Campeão: '+esc(e.winners.map(id=>db.teams.find(t=>t.id===id)?.name).join(' / ')):'Campeão sem registro'} · ${e.roster.length?e.roster.length+' jogadores na escalação':e.rosterReference?e.rosterReference.players.length+' jogadores · elenco anual':'Escalação parcial'}</small></span>${e.major?'<b class="hub-badge">MAJOR</b>':'<b>↗</b>'}</a>`).join(''):'<p class="hub-empty">Nenhum campeonato corresponde aos filtros. Experimente outro ano ou organizadora.</p>';}
function tournaments(){screen.innerHTML=header('HBSTV · CAMPEONATOS','Cada conquista tem uma história.','Explore os campeões, elencos e premiações de cada edição.')+`<div class="hub-filters"><label>Buscar campeonato<input id="hub-event-search" type="search" value="${esc(query)}" placeholder="Torneio ou campeão…"></label><label>Ano<select id="hub-event-year"><option value="">Todos</option>${yearOptions()}</select></label><label>Organizadora<select id="hub-event-org"><option value="">Todas</option>${orgOptions()}</select></label></div><div class="hub-list-heading"><label class="hub-check"><input type="checkbox" id="hub-major-only" ${majorOnly?'checked':''}> Apenas Majors</label><span id="hub-event-count" aria-live="polite"></span><button data-reset-events class="hub-text-button">Limpar filtros</button></div><div id="hub-event-list"></div>`;eventList();}
function championship(id){const e=H.event(id);if(!e){screen.innerHTML=header('CAMPEONATOS','Registro não encontrado','Confira os campeonatos disponíveis.')+'<a href="#campeonatos">Ver campeonatos →</a>';return;}screen.innerHTML=`<div class="hub-breadcrumb"><a href="#campeonatos">← Campeonatos</a>${share}</div>`+header(e.year+' · '+e.organizer,e.title,e.major?'Major · edição histórica':'Campeonato · edição histórica')+`<div class="hub-event-summary">${window.renderOrganizationEmblem(e.title)}<div><span class="eyebrow">CAMPEÃO REGISTRADO</span>${e.winners.length?e.winners.map(id=>`<a href="#time/${id}">${esc(db.teams.find(t=>t.id===id)?.name)} ↗</a>`).join(''):'<p>Sem registro disponível</p>'}</div>${e.major?'<span class="hub-badge">MAJOR</span>':''}</div><div class="hub-awards"><section><h3>MVP</h3>${e.mvps.length?e.mvps.map(linkPlayer).join(''):'<p>Sem registro de MVP para esta edição.</p>'}</section><section><h3>EVPs</h3>${e.evps.length?e.evps.map(linkPlayer).join(''):'<p>Sem registro de EVPs para esta edição.</p>'}</section></div><section class="hub-section"><h3>${e.rosterReference?"Elenco de referência · "+e.year:"Escalação campeã"} <small>${(e.rosterReference?.players||e.roster).length} registrados</small></h3>${e.rosterReference?'<p class="hub-note">Elenco anual da equipe usado como referência para esta edição. A formação específica do torneio ainda não está detalhada.</p>':''}<div class="hub-player-grid">${(e.rosterReference?.players||e.roster).length?(e.rosterReference?.players||e.roster).map(linkPlayer).join(''):'<p>O título está documentado; a escalação vencedora ainda não foi detalhada.</p>'}</div></section><section class="hub-section"><h3>Fontes e cobertura</h3><p>Os nomes são unificados por jogador. A ausência de um nome ou prêmio indica falta de registro nesta edição. Os demais participantes e resultados completos podem não estar documentados.</p>${e.notes.map(n=>`<p>${esc(n)}</p>`).join('')}<div class="hub-source-links">${e.sources.filter(s=>s!=='owner-confirmed').map(s=>`<a href="#acervo/${esc(s)}">Consultar registro original ↗</a>`).join('')}${e.sources.includes('owner-confirmed')?'<span>Informação confirmada pelo responsável pelo site</span>':''}</div>${e.images.length?`<details><summary>Registros visuais da edição (${e.images.length})</summary>${e.images.map(src=>`<a href="${esc(src)}" target="_blank" rel="noopener"><img loading="lazy" class="hub-record-image" src="${esc(src)}" alt="Registro de ${esc(e.title)}"></a>`).join('')}</details>`:''}</section>`;document.title=e.title+' — HBSTV.ORG';}
function playerDirectory(){screen.innerHTML=header('HBSTV · JOGADORES','Quem fez história.','Busque por nick, nome ou nome antigo. Cada jogador tem um perfil único.')+`<label class="hub-search-label">Buscar jogador<input id="hub-player-search" type="search" placeholder="Nome ou nick…" value="${esc(playerQuery)}"></label><div class="hub-player-directory" id="hub-player-list"></div>`;playerList();}
function playerList(){const q=H.key(playerQuery),list=db.players.filter(p=>H.key(p.name+' '+p.realNames.join(' ')+' '+p.aliases.join(' ')).includes(q)||p.id===q);document.querySelector('#hub-player-list').innerHTML=list.length?list.map(p=>linkPlayer(p.id)).join(''):'<p class="hub-empty">Nenhum jogador encontrado.</p>';}
function profile(id){const p=H.person(id);if(!p){screen.innerHTML=header('JOGADORES','Jogador não encontrado','Busque um jogador cadastrado.')+'<a href="#jogadores-todos">Ver jogadores →</a>';return;}const h=players.find(x=>H.key(x.name)===p.id),dialog=document.querySelector('#detail');if(dialog.open)dialog.close();if(h)window.showPlayerProfile(h);else window.showRegisteredPlayerProfile(p.id);const content=document.querySelector('#detail-content').innerHTML;dialog.close();screen.innerHTML=`<div class="hub-breadcrumb"><a href="#jogadores-todos">← Jogadores</a>${h?'<span class="hub-badge">HALL OF FAME</span>':''}${share}</div><div class="hub-full-profile">${content}</div><section class="hub-section"><h3>Registros competitivos</h3><p>Consulte as edições relacionadas ao jogador e suas fontes. Os totais históricos do Hall of Fame podem incluir conquistas ainda sem ficha individual.</p><div class="hub-source-links">${db.events.filter(e=>[...e.roster,...e.mvps,...e.evps].includes(p.id)).map(e=>`<a href="${H.eventHref(e.id)}">${e.year} · ${esc(e.title)} ↗</a>`).join('')||'<p>As fichas individuais de campeonato ainda não estão disponíveis.</p>'}</div></section>`;document.title=p.name+' — HBSTV.ORG';}
const articles=[{id:"4i20-sete-temporadas",title:"4i20: sete temporadas entre os melhores",category:"Destaque histórico",text:"Duas vezes #1 e sete participações no Top 20.",href:"#jogador/4i2o",cta:"Ver perfil"},{id:'top20-2025',title:'tabsenn no topo do ranking de 2025',season:2025,category:'Rankings',text:'Gustavo “tabsenn” lidera o Top 20 de 2025. ZDR e 4i20 completam as três primeiras posições da lista registrada pela BCN.',href:'#acervo/top-20-players',cta:'Consultar os rankings anuais'},{id:'majors-tsl',title:'Os Majors da TSL e seus registros históricos',category:'Circuitos',text:'As edições de Major da TSL fazem parte do histórico competitivo preservado pelo RANK S. Confira as fichas de cada edição para consultar campeão, escalação e premiações disponíveis.',href:'#campeonatos',cta:'Explorar campeonatos'},{id:'ik-legends-2025',title:'IK em 2025: sete títulos e o topo do ranking',season:2025,category:'Equipes',text:'A IK ocupa o primeiro lugar no ranking anual de equipes de 2025. O perfil da equipe reúne as conquistas e os jogadores citados nos registros da temporada.',href:'#time/iklegends',cta:'Ver histórico da IK'},{id:'awards-2025',title:'Os vencedores das premiações de 2025',season:2025,category:'Awards',text:'As premiações individuais e coletivas estão reunidas por ano e categoria. Consulte os vencedores, as organizadoras e os registros visuais usados como fonte.',href:'#acervo/awards',cta:'Ver os Awards'},{id:'ranking-2017',title:'SanSey lidera o Top 20 de 2017',season:2017,category:'História',text:'O ranking mundial de 2017 coloca SanSey em primeiro lugar, seguido por 4i20 e Galaxy. A lista integra o histórico anual dos jogadores do Block Strike.',href:'#acervo/top-20-players',cta:'Consultar ranking histórico'}];
function news(id){if(id==="ik-legends-2025"){screen.innerHTML=`<div class="hub-breadcrumb"><a href="#novidades">← Novidades</a>${share}</div>`+window.renderIKArticle();return;}if(id==="4i20-sete-temporadas"){screen.innerHTML=`<div class="hub-breadcrumb"><a href="#novidades">← Novidades</a>${share}</div>`+window.render4i20Article();return;}const a=articles.find(a=>a.id===id);if(!a){screen.innerHTML=header('HBSTV · NOVIDADES','Histórias do competitivo','Resumos editoriais a partir dos registros históricos.')+articles.map(a=>`<a class="hub-news-card" href="#noticia/${a.id}"><small>${a.category}${a.season?' · temporada '+a.season:''}</small><h3>${a.title}</h3><span>Consultar história ↗</span></a>`).join('');return;}screen.innerHTML=`<div class="hub-breadcrumb"><a href="#novidades">← Novidades</a>${share}</div>`+header(a.category,a.title,'Resumo histórico · edição editorial de 3 de novembro de 2026')+`<article class="hub-article"><p>${esc(a.text)}</p>${a.season?`<p class="hub-note">Temporada retratada: ${a.season}. A data editorial identifica a organização deste resumo no HBSTV.</p>`:''}<a class="hub-button" href="${a.href}">${a.cta} ↗</a><p>Fonte: registros históricos do RANK S preservados no site.</p></article>`;}
window.renderHubRoute=()=>{screen.hidden=true;let hash=location.hash,id;try{id=decodeURIComponent(hash.split('/').slice(1).join('/'));}catch{id='';}if(['#campeonatos','#arquivo'].includes(hash))tournaments();else if(hash.startsWith('#campeonato/'))championship(id);else if(hash==='#jogadores-todos')playerDirectory();else if(hash.startsWith('#jogador/'))profile(id);else if(hash==='#novidades')news();else if(hash.startsWith('#noticia/'))news(id);else if(hash==='#manutencao'){window.renderMaintenance(screen);}else return false;screen.hidden=false;document.title=(screen.querySelector('h2')?.textContent||'HBSTV')+' — HBSTV.ORG';return true;};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-copy-link]');if(b){try{await navigator.clipboard.writeText(location.href);b.nextElementSibling.textContent='Link copiado';}catch{b.nextElementSibling.textContent='Copie o endereço pela barra do navegador.';}}if(e.target.closest('[data-reset-events]')){query=year=organizer='';majorOnly=false;tournaments();}});
document.addEventListener('input',e=>{if(e.target.id==='hub-event-search'){query=e.target.value;eventList();}if(e.target.id==='hub-player-search'){playerQuery=e.target.value;playerList();}});
document.addEventListener('change',e=>{if(e.target.id==='hub-event-year')year=e.target.value;if(e.target.id==='hub-event-org')organizer=e.target.value;if(e.target.id==='hub-major-only')majorOnly=e.target.checked;if(e.target.id.startsWith('hub-event-')||e.target.id==='hub-major-only')eventList();});
document.addEventListener('click',e=>{const p=e.target.closest('[data-player],[data-entity-player],[data-hof-profile]');if(p){const id=p.dataset.entityPlayer||H.key(players[Number(p.dataset.player??p.dataset.hofProfile)]?.name);if(H.person(id)){e.preventDefault();e.stopImmediatePropagation();document.querySelector('#detail').close();document.querySelector('#entity-suggestions').hidden=true;document.querySelector('#search').value='';location.hash=H.playerHref(id);return;}}const t=e.target.closest('[data-club-tournament]');if(t){e.preventDefault();e.stopImmediatePropagation();location.hash=H.eventHref(t.dataset.clubTournament);return;}const old=e.target.closest('[data-event]');if(old){const raw=events[+old.dataset.event],event=db.events.find(x=>x.year===raw?.year&&(x.title===raw.title||x.sources.includes(raw.source)&&x.title===raw.blocks?.find(b=>b.level===4)?.text?.replace(/\s*\[TIER[^\]]*\]/gi,'')));if(event){e.preventDefault();e.stopImmediatePropagation();location.hash=H.eventHref(event.id);}}},true);
})();
